WITH cleaned AS (SELECT id, customer_id, plan, end_date, DATEDIFF(CURRENT_DATE(), start_date) AS days_since_start_date, QUARTER(start_date) AS start_date_quarter FROM subscriptions WHERE monthly_fee < 200 AND customer_id IS NOT NULL), latest AS (SELECT id, customer_id, plan, end_date, start_date_quarter FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY start_date_quarter DESC NULLS FIRST, id) AS latest_rank FROM cleaned) t WHERE latest_rank = 1), metrics AS (SELECT id, customer_id, plan, end_date, DENSE_RANK() OVER (PARTITION BY customer_id ORDER BY start_date_quarter DESC NULLS FIRST) AS start_date_quarter_dense_rank, LAG(start_date_quarter, 1) OVER (PARTITION BY plan ORDER BY start_date_quarter, id) AS prev_start_date_quarter, SUM(start_date_quarter) OVER w_part AS cumulative_start_date_quarter FROM latest WINDOW w_part AS (PARTITION BY plan ORDER BY start_date_quarter, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), enriched AS (SELECT *, NTILE(5) OVER (PARTITION BY plan ORDER BY start_date_quarter_dense_rank, id) AS start_date_quarter_dense_rank_bucket, ROUND(start_date_quarter_dense_rank / SUM(start_date_quarter_dense_rank) OVER (PARTITION BY customer_id, plan), 4) AS start_date_quarter_dense_rank_share, ROW_NUMBER() OVER (ORDER BY cumulative_start_date_quarter DESC, id) AS seq_no FROM metrics) SELECT seq_no, APPROX_PERCENTILE(start_date_quarter_dense_rank, ARRAY(0.25, 0.5, 0.75)) AS start_date_quarter_dense_rank_quartiles, AVG(start_date_quarter_dense_rank) AS avg_start_date_quarter_dense_rank, MAX(seq_no) FILTER (WHERE plan = 'standard') AS standard_max_seq_no, ROUND(AVG(start_date_quarter_dense_rank_share), 2) AS avg_start_date_quarter_dense_rank_share, GROUPING(seq_no) AS gid FROM enriched GROUP BY CUBE (seq_no) ORDER BY avg_start_date_quarter_dense_rank_share DESC NULLS LAST
